const[firstName,setFirstName]=useState("");const[lastName,setLastName]=useState("");const[username,setUsername]=useState("");const[country,setCountry]=useState("");const[joinedDate,setJoinedDate]=useState("");
const[sellerBalance,setSellerBalance]=useState(0);const[usdtBalance,setUsdtBalance]=useState(0);const[usdcBalance,setUsdcBalance]=useState(0);const[withdrawCurrency,setWithdrawCurrency]=useState<"USDT"|"USDC">("USDT");const[sellerPending,setSellerPending]=useState(0);const[sellerTotalEarnings,setSellerTotalEarnings]=useState(0);const[sellerActiveOrders,setSellerActiveOrders]=useState(0);const[sellerActiveListings,setSellerActiveListings]=useState(0);const[withdrawalRequest,setWithdrawalRequest]=useState<{gross:number;fee:number;net:number;status:"pending"}|null>(null);const[userOrders,setUserOrders]=useState<UserOrder[]>([]);const[ordersLoading,setOrdersLoading]=useState(false);
const[kycVerified,setKycVerified]=useState(false);const[kycStatus,setKycStatus]=useState<"not-started"|"pending"|"approved"|"rejected"|"reupload-required">("not-started");const[kycReviewNote,setKycReviewNote]=useState("");const[idDocument,setIdDocument]=useState<File|null>(null);const[selfieDocument,setSelfieDocument]=useState<File|null>(null);const[kycBusy,setKycBusy]=useState(false);const[documentType,setDocumentType]=useState<"ID"|"PASSPORT">("ID");const[orderCreated,setOrderCreated]=useState(false);const[orderGig,setOrderGig]=useState<Gig>(emptyGig);const[disputeOpen,setDisputeOpen]=useState(false);const[toolOpen,setToolOpen]=useState("01");const[growthOpen,setGrowthOpen]=useState("01");const[currency,setCurrency]=useState("EUR");const[language,setLanguage]=useState<keyof typeof translations>("EN");const[cookieVisible,setCookieVisible]=useState(false);const[maintenance,setMaintenance]=useState(false);const[highContrast,setHighContrast]=useState(false);const[sellerAway,setSellerAway]=useState(false);
const profileComplete=Boolean(firstName.trim()&&lastName.trim()&&country.trim());
const tr=(key:keyof typeof translations.EN)=>translations[language][key];
const uploadAccountFile=(file:File,path:string,label:string)=>new Promise<string>((resolve,reject)=>{const task=uploadBytesResumable(ref(getClientStorage(),path),file,{contentType:file.type});const timer=setTimeout(()=>{task.cancel();reject(new Error(`${label} could not connect to Firebase Storage. Check Storage setup and try again.`))},45000);task.on("state_changed",undefined,error=>{clearTimeout(timer);reject(error)},async()=>{clearTimeout(timer);try{resolve(await getDownloadURL(task.snapshot.ref))}catch(error){reject(error)}})});
const loadProfile=async()=>{const user=getClientAuth().currentUser;if(!user)return;try{const token=await user.getIdToken();const response=await fetch("/api/profile",{headers:{authorization:`Bearer ${token}`},cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to load profile");const profile=data.profile||{},completed=Boolean(String(profile.firstName||"").trim()&&String(profile.lastName||"").trim()&&String(profile.country||"").trim());setFirstName(profile.firstName||"");setLastName(profile.lastName||"");setUsername(profile.username||"");setCountry(profile.country||"");setProfileImage(profile.profileImageUrl||"");if(profile.mode==="SELLER"&&completed)setMode("SELLER");else setMode("BUYING");setSellerBalance(Number(profile.availableBalanceCents||0)/100);setUsdtBalance(Number(profile.usdtBalanceCents||0)/100);setUsdcBalance(Number(profile.usdcBalanceCents||0)/100);setSellerPending(Number(profile.pendingEarningsCents||0)/100);setSellerTotalEarnings(Number(profile.totalEarningsCents||0)/100);const status=profile.kycStatus||"not-started";setKycStatus(status);setKycReviewNote(profile.kycReviewNote||"");setKycVerified(status==="approved");setSellerBalance(Number(profile.availableBalanceCents||0)/100);setSellerPending(Number(profile.pendingEarningsCents||0)/100);setSellerTotalEarnings(Number(profile.totalEarningsCents||0)/100);setSellerActiveOrders(Number(profile.activeOrderCount||0));setSellerActiveListings(Number(profile.activeListingCount||0));setPhoneVerified(Boolean(profile.phoneVerified));setPhoneOnFile(profile.phoneNumber||"");if(profile.joinedAt)setJoinedDate(new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"long",year:"numeric"}).format(new Date(profile.joinedAt)))}catch(error){flash(error instanceof Error?error.message:"Unable to load profile")}};
const saveProfile=async()=>{const user=getClientAuth().currentUser;if(!user){flash("Please sign in again.");return}try{let profileImageUrl=profileImage;if(profileImageFile)profileImageUrl=await uploadAccountFile(profileImageFile,`profiles/${user.uid}/profile-${Date.now()}-${profileImageFile.name}`,"Profile photo");const token=await user.getIdToken(true);const response=await fetch("/api/profile",{method:"PATCH",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({firstName,lastName,username,country,mode,profileImageUrl})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to save profile");setProfileImage(profileImageUrl);setProfileImageFile(null);flash(`${mode==="BUYING"?"Buyer":"Seller"} profile saved permanently.`)}catch(error){flash(error instanceof Error?error.message:"Unable to save profile")}};
const submitKyc=async()=>{const user=getClientAuth().currentUser;if(!user||!idDocument||!selfieDocument)return;if(!profileComplete){setAccountPanel("profile");flash("Complete and save your first name, surname and country before submitting KYC.");return}setKycBusy(true);try{const token=await user.getIdToken(true);const upload=async(file:File,kind:"identity"|"selfie")=>{const form=new FormData();form.append("file",file);form.append("kind",kind);const response=await fetch("/api/kyc/upload",{method:"POST",headers:{authorization:`Bearer ${token}`},body:form});const text=await response.text();let data:{url?:string;error?:string}={};try{data=text?JSON.parse(text):{}}catch{throw new Error(`KYC upload returned an invalid response (${response.status})`)}if(!response.ok||!data.url)throw new Error(data.error||`Unable to upload ${kind} image`);return data.url};flash("Uploading identity document securely…");const idDocumentUrl=await upload(idDocument,"identity");flash("Uploading your holding-document selfie securely…");const selfieDocumentUrl=await upload(selfieDocument,"selfie");const response=await fetch("/api/kyc",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({documentType,idDocumentUrl,selfieDocumentUrl})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to submit KYC");setKycStatus("pending");setKycReviewNote("");setKycVerified(false);setIdDocument(null);setSelfieDocument(null);flash("KYC submitted and saved. Waiting for administrator approval.")}catch(error){flash(error instanceof Error?error.message:"Unable to submit KYC")}finally{setKycBusy(false)}};
const loadMyServices=async()=>{const user=getClientAuth().currentUser;if(!user){flash("Please sign in again.");return}setServicesLoading(true);try{const token=await user.getIdToken();const response=await fetch("/api/listings?mine=1",{headers:{authorization:`Bearer ${token}`},cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to load your services");setSellerServices(data.listings||[])}catch(error){flash(error instanceof Error?error.message:"Unable to load your services")}finally{setServicesLoading(false)}};
const deleteMyService=async(service:SellerService)=>{if(!window.confirm(`Delete “${service.title||"this service"}” from the marketplace? This cannot be restored by you.`))return;const user=getClientAuth().currentUser;if(!user){flash("Please sign in again.");return}try{const token=await user.getIdToken(true);const response=await fetch(`/api/listings?id=${encodeURIComponent(service.id)}`,{method:"DELETE",headers:{authorization:`Bearer ${token}`}});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to delete this service");setSellerServices(items=>items.filter(item=>item.id!==service.id));await loadMarketplace();flash("Service deleted from the marketplace.")}catch(error){flash(error instanceof Error?error.message:"Unable to delete this service")}};
const payListingFee=async(service:SellerService)=>{const user=getClientAuth().currentUser;if(!user){flash("Please sign in again.");return}try{const token=await user.getIdToken(true);const response=await fetch("/api/stripe/checkout",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({purpose:"listing-credits",listingId:service.id})});const data=await response.json();if(!response.ok||!data.url)throw new Error(data.error||"Unable to open Stripe checkout");location.assign(data.url)}catch(error){flash(error instanceof Error?error.message:"Unable to open Stripe checkout")}};
const loadCustomRecipients=async()=>{const user=getClientAuth().currentUser;if(!user){flash("Please sign in again.");return}setCustomRecipientsLoading(true);try{const token=await user.getIdToken();const response=await fetch("/api/custom-orders/recipients",{headers:{authorization:`Bearer ${token}`},cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to load message contacts");setCustomRecipients(data.recipients||[])}catch(error){setCustomStatus(error instanceof Error?error.message:"Unable to load message contacts")}finally{setCustomRecipientsLoading(false)}};
const sendCustomOffer=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const user=getClientAuth().currentUser;if(!user){flash("Please sign in again.");return}const form=e.currentTarget;const fd=new FormData(form);const recipientId=String(fd.get("recipientId")||"");const title=String(fd.get("title")||"").trim();const details=String(fd.get("details")||"").trim();const price=Number(fd.get("price")||0);const currency=fd.get("currency")==="USDC"?"USDC":"USDT";if(!recipientId||!title||!details||!price){setCustomStatus("Please fill in recipient, title, details and price.");return}setCustomSending(true);setCustomStatus("Sending custom offer…");try{const token=await user.getIdToken();const attachments=customFiles.map(file=>({name:file.name,size:file.size,type:file.type}));const response=await fetch("/api/custom-orders",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({recipientId,title,details,price,currency,attachments})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not send custom offer.");setCustomStatus("Custom offer sent successfully.");form.reset();setCustomFiles([])}catch(error){setCustomStatus(error instanceof Error?error.message:"Could not send custom offer.")}finally{setCustomSending(false)}};
const loadOrders=async()=>{const user=getClientAuth().currentUser;if(!user)return;setOrdersLoading(true);try{const token=await user.getIdToken();const response=await fetch("/api/orders",{headers:{authorization:`Bearer ${token}`},cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to load orders");setUserOrders(data.orders||[]);}catch(error){flash(error instanceof Error?error.message:"Unable to load orders")}finally{setOrdersLoading(false)}};
const loadNotifications=async()=>{const user=getClientAuth().currentUser;if(!user)return;try{const token=await user.getIdToken();const response=await fetch("/api/notifications",{headers:{authorization:`Bearer ${token}`},cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to load notifications");setNotifications(data.notifications||[]);}catch(error){flash(error instanceof Error?error.message:"Unable to load notifications")}};
const markNotificationRead=async(id:string)=>{const user=getClientAuth().currentUser;if(!user)return;setNotifications(items=>items.map(item=>item.id===id?{...item,read:true}:item));try{const token=await user.getIdToken();await fetch("/api/notifications",{method:"PATCH",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({id})});}catch{}};
const markAllNotificationsRead=async()=>{const user=getClientAuth().currentUser;if(!user)return;setNotifications(items=>items.map(item=>({...item,read:true})));try{const token=await user.getIdToken();await fetch("/api/notifications",{method:"PATCH",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({all:true})});}catch{}};const clearAllNotifications=async()=>{const user=getClientAuth().currentUser;if(!user)return;if(!notifications.length)return;if(!window.confirm("Clear all notifications permanently? This cannot be undone."))return;try{const token=await user.getIdToken();const response=await fetch("/api/notifications",{method:"DELETE",headers:{authorization:`Bearer ${token}`}});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to clear notifications");setNotifications([]);flash("All notifications were permanently removed.");}catch(error){flash(error instanceof Error?error.message:"Unable to clear notifications")}};
const reportMessage=async(conversationId:string,messageId:string,reason="Inappropriate or unsafe content",attachmentIndex?:number)=>{const user=getClientAuth().currentUser;if(!user)return;const custom=window.prompt("Why are you reporting this message or upload?",reason);if(custom===null||!custom.trim())return;try{const token=await user.getIdToken(true);const response=await fetch("/api/reports",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({conversationId,messageId,attachmentIndex,reason:custom.trim()})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to submit report");flash("Report sent to the administrator.");}catch(error){flash(error instanceof Error?error.message:"Unable to submit report")}};
const loadInbox=async()=>{const user=getClientAuth().currentUser;if(!user)return;setInboxLoading(true);setCurrentUid(user.uid);try{const token=await user.getIdToken();const response=await fetch("/api/messages",{headers:{authorization:`Bearer ${token}`},cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to load inbox");const conversations:InboxConversation[]=data.conversations||[];setInboxConversations(conversations);setSelectedConversationId(current=>conversations.some(item=>item.id===current)?current:(conversations[0]?.id||""))}catch(error){flash(error instanceof Error?error.message:"Unable to load inbox")}finally{setInboxLoading(false)}};
const loadCustomOffers=async()=>{const user=getClientAuth().currentUser;if(!user)return;try{const token=await user.getIdToken();const response=await fetch("/api/custom-orders",{headers:{authorization:`Bearer ${token}`},cache:"no-store"});const data=await response.json();if(response.ok)setCustomOffers(data.offers||[])}catch{}};
const acceptCustomOffer=async(offerId:string)=>{const user=getClientAuth().currentUser;if(!user){flash("Please sign in again.");return}setOfferActionBusy(true);try{const token=await user.getIdToken(true);const response=await fetch("/api/custom-orders",{method:"PATCH",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({offerId,action:"accept"})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to accept this offer.");setOfferPayment({orderId:data.orderId,orderNumber:data.orderNumber,amountCents:data.amountCents,depositAddress:data.depositAddress,network:data.network,currency:data.currency});await loadCustomOffers();flash("Custom offer accepted — send payment to complete the order.")}catch(error){flash(error instanceof Error?error.message:"Unable to accept this offer.")}finally{setOfferActionBusy(false)}};
