const submitOfferTx=async()=>{if(!offerPayment)return;if(offerTxHash.trim().length<16){flash(`Enter the ${offerPayment.currency} transaction hash after sending the payment.`);return}const user=getClientAuth().currentUser;if(!user){flash("Please sign in again.");return}setOfferActionBusy(true);try{const token=await user.getIdToken();const response=await fetch("/api/crypto/checkout",{method:"PUT",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({orderId:offerPayment.orderId,txHash:offerTxHash.trim()})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not submit payment reference");flash(`Payment submitted to admin for verification. Order #${offerPayment.orderNumber||offerPayment.orderId}.`);setOfferPayment(null);setOfferTxHash("");loadOrders()}catch(error){flash(error instanceof Error?error.message:"Could not submit payment reference")}finally{setOfferActionBusy(false)}};
const inboxUploadFile=async(file:File,index:number)=>{if(file.size<=0||file.size>100*1024*1024)throw new Error(`“${file.name}” is larger than 100 MB.`);const user=getClientAuth().currentUser;if(!user)throw new Error("Please sign in again.");const conversation=inboxConversations.find(item=>item.id===selectedConversationId);if(!conversation)throw new Error("Choose a conversation first.");const safeName=file.name.replace(/[^a-zA-Z0-9._()\- ]/g,"_").slice(0,180)||`file-${index+1}`;const path=`messages/${conversation.id}/${user.uid}/${Date.now()}-${crypto.randomUUID()}-${safeName}`;return new Promise<InboxAttachment>((resolve,reject)=>{const task=uploadBytesResumable(ref(getClientStorage(),path),file,{contentType:file.type||"application/octet-stream"});task.on("state_changed",undefined,error=>reject(error),async()=>{try{resolve({name:file.name,url:await getDownloadURL(task.snapshot.ref),size:file.size,type:file.type||"application/octet-stream",path})}catch(error){reject(error)}})});};
const deliverOrder=async()=>{if(!deliverableOrder||deliveryBusy)return;if(!deliveryMessage.trim()&&!deliveryFiles.length){flash("Add a delivery message or attach at least one file.");return}const user=getClientAuth().currentUser;if(!user)return;setDeliveryBusy(true);try{const attachments:InboxAttachment[]=[];for(let i=0;i<deliveryFiles.length;i++){flash(`Uploading ${deliveryFiles[i].name} (${i+1}/${deliveryFiles.length})…`);attachments.push(await inboxUploadFile(deliveryFiles[i],i));}const token=await user.getIdToken(true);const response=await fetch("/api/orders/delivery",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({orderId:deliverableOrder.id,message:deliveryMessage.trim(),attachments})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to deliver this order");flash("Order marked as delivered. The buyer has been notified.");setDeliveryMessage("");setDeliveryFiles([]);await Promise.all([loadOrders(),loadInbox()])}catch(error){flash(error instanceof Error?error.message:"Unable to deliver this order")}finally{setDeliveryBusy(false)}};
const requestOrderRevision=async()=>{if(!deliveredOrderForBuyer||revisionBusy)return;if(revisionMessage.trim().length<10){flash("Describe the requested changes (minimum 10 characters).");return}const user=getClientAuth().currentUser;if(!user)return;setRevisionBusy(true);try{const token=await user.getIdToken(true);const response=await fetch("/api/orders/revision",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({orderId:deliveredOrderForBuyer.id,message:revisionMessage.trim()})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to request a revision");flash("Revision requested. The seller has been notified.");setRevisionMessage("");await Promise.all([loadOrders(),loadInbox()])}catch(error){flash(error instanceof Error?error.message:"Unable to request a revision")}finally{setRevisionBusy(false)}};
const openInboxDispute=async()=>{if(!deliveredOrderForBuyer||inboxDisputeBusy)return;if(inboxDisputeNote.trim().length<10){flash("Explain the problem with this order (minimum 10 characters).");return}const user=getClientAuth().currentUser;if(!user)return;setInboxDisputeBusy(true);try{const token=await user.getIdToken(true);const response=await fetch("/api/orders",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({orderId:deliveredOrderForBuyer.id,reason:inboxDisputeNote.trim()})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to open dispute");flash("Dispute sent to the administrator.");setInboxDisputeNote("");await Promise.all([loadOrders(),loadInbox()])}catch(error){flash(error instanceof Error?error.message:"Unable to open dispute")}finally{setInboxDisputeBusy(false)}};
const acceptOrder=async()=>{if(!deliveredOrderForBuyer||acceptBusy)return;if(!window.confirm("Accept this delivery and release payment to the seller now? This cannot be undone."))return;const user=getClientAuth().currentUser;if(!user)return;setAcceptBusy(true);try{const token=await user.getIdToken(true);const response=await fetch("/api/orders/accept",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({orderId:deliveredOrderForBuyer.id})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to accept this order");flash("Order accepted. Payment released to the seller.");await Promise.all([loadOrders(),loadInbox()])}catch(error){flash(error instanceof Error?error.message:"Unable to accept this order")}finally{setAcceptBusy(false)}};
const sendInboxReply=async()=>{const user=getClientAuth().currentUser,conversation=inboxConversations.find(item=>item.id===selectedConversationId);if(!user||!conversation||(!replyText.trim()&&!replyAttachments.length)||replyBusy)return;setReplyBusy(true);try{const attachments:InboxAttachment[]=[];for(let i=0;i<replyAttachments.length;i++){flash(`Uploading ${replyAttachments[i].name} (${i+1}/${replyAttachments.length})…`);attachments.push(await inboxUploadFile(replyAttachments[i],i));}const token=await user.getIdToken(true);const response=await fetch("/api/messages",{method:"POST",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({recipientId:conversation.otherUser.id,text:replyText.trim(),attachments})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to send reply");setReplyText("");setReplyAttachments([]);await loadInbox()}catch(error){flash(error instanceof Error?error.message:"Unable to send reply")}finally{setReplyBusy(false)}};
const loadMarketplace=async()=>{try{const response=await fetch("/api/listings",{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to load services");const colors=["linear-gradient(135deg,#e5f0ff,#90b9ff)","linear-gradient(135deg,#fff0e8,#ffb79c)","linear-gradient(135deg,#eee8ff,#b5a0ff)","linear-gradient(135deg,#e5fff4,#8ee0bd)"];setMarketplaceGigs((data.listings||[]).map((item:Record<string,unknown>,index:number)=>({id:String(item.id),cat:String(item.category||"Other"),subcategory:String(item.subcategory||item.category||"Service"),title:String(item.title||"Untitled service"),seller:String(item.sellerName||"SaharaSnow seller"),sellerId:String(item.sellerId||""),sellerImage:String(item.sellerProfileImage||"")||undefined,sellerCountry:String(item.sellerCountry||""),sellerOnline:Boolean(item.sellerOnline),price:Number(item.priceCents||0)/100,emoji:"😊",reviews:0,bg:colors[index%colors.length],tag:Array.isArray(item.tags)&&item.tags.length?String(item.tags[0]):String(item.subcategory||"Service"),image:Array.isArray(item.photoUrls)&&item.photoUrls.length?String(item.photoUrls[0]):undefined,description:String(item.description||"")})));setServicesError("")}catch(error){setServicesError(error instanceof Error?error.message:"Unable to load services")}};
