{servicesError&&<p className="listingNotice">{servicesError}</p>}<div id="service-results" className="grid">{results.map(g=>{const stats=cardStats[g.id];const tier=sellerTier(stats?.orderCount||0);return <article id={`service-${g.id}`} key={g.id} tabIndex={0} onClick={()=>location.assign(servicePath(g))} onKeyDown={e=>{if(e.key==="Enter")location.assign(servicePath(g))}}><div className="visual" style={{background:g.bg}}>{g.image&&<img src={g.image} alt={g.title}/>}<span>{g.tag}</span><FavoriteButton listingId={g.id} className="favouriteButton"/>{!g.image&&<b>✦</b>}</div>
<div className="cardBody"><a className="seller sellerLink" href={sellerPath(g)} onClick={e=>e.stopPropagation()}>{g.sellerImage?<img src={g.sellerImage} alt={g.seller}/>:<i>{g.seller[0]}</i>}<div><b>{g.seller}</b><span className={`presenceText ${g.sellerOnline?"statusOnline":"statusAway"}`}>{g.sellerOnline?"Online":"Away"}</span>{g.sellerCountry&&<span className="sellerCountryRow">{countryFlagUrl(g.sellerCountry,20)&&<img src={countryFlagUrl(g.sellerCountry,20)} alt=""/>}{g.sellerCountry}</span>}<span className={`sellerTier ${tier.cls}`}>{tier.emoji} {tier.label}</span></div></a><h3>{g.title}</h3><div className="meta"><span>★ <small>{stats&&stats.averageRating>0?stats.averageRating.toFixed(1):"—"} ({stats?.reviewCount||0})</small></span><span className="orderCount">🛒 {stats?.orderCount||0} orders</span><span>From <b>${g.price}</b></span></div><div className="cardFooter"><span className="engagementCount">{stats?.shareCount||0} shares · {stats?.favoriteCount||0} favourites</span><button type="button" className="shareToggle" data-sahara-share data-listing-id={g.id} data-share-title={g.title} data-share-url={servicePath(g)} aria-label="Share service">↗</button></div></div></article>})}</div>
