{growthOpen==="04"&&<div className="packageCompare">{[["Basic","€85","1 concept"],["Standard","€140","3 concepts"],["Premium","€220","5 concepts + source files"]].map(p=><div key={p[0]}><b>{p[0]}</b><strong>{p[1]}</strong><small>{p[2]}</small><button>Choose</button></div>)}</div>}
{growthOpen==="05"&&<div className="customOffer"><input placeholder="Custom offer title"/><input placeholder="Price €"/><select><option>3 days</option><option>7 days</option><option>14 days</option></select><button onClick={()=>flash("Custom offer sent.")}>Send offer</button></div>}
{growthOpen==="06"&&<div className="tipButtons">{[5,10,20,50].map(n=><button key={n} onClick={()=>flash(`€${n} tip added for seller.`)}>€{n}</button>)}</div>}
{growthOpen==="07"&&<div className="sellerDiscount"><span>SELLER-ISSUED ONLY</span>{mode==="SELLER"?<><input defaultValue="THANKYOU10" aria-label="Discount code"/><select aria-label="Discount amount"><option>10% off</option><option>15% off</option><option>€5 off</option></select><select aria-label="Apply discount to"><option>Selected service</option><option>Custom offer</option><option>All my services</option></select><button onClick={()=>flash("Seller discount code created and applied.")}>Create seller code</button></>:<><input placeholder="Enter seller discount code"/><button onClick={()=>flash("Seller-issued discount code redeemed.")}>Redeem code</button></>}</div>}
{growthOpen==="08"&&<div className="supportTicket"><select><option>Order problem</option><option>Payment</option><option>Account</option></select><textarea placeholder="Describe how we can help"/><button onClick={()=>flash("Support ticket #1001 created.")}>Create ticket</button></div>}
